(911, 55, 432343458, 874705997, 8704, 1645215760, 0, 0, 0, 0, 400, -42000, 4000, 3100, 273, 6, 17, 17, 67, 1.0, 0.25, 7, 5, 'Silvermoon City', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 16712190, 'The capital of Quel''Thalas, home of the blood elves.  Though nearly destroyed by Arthas'' attack on the Sunwell, Silvermoon is once again a thriving city.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 16712190),
